<div class="page-head"><div><div class="page-kicker">Inventory</div><h1 class="page-title">Current stock</h1><p class="page-subtitle">Live balances calculated from opening stock and confirmed ledger movements.</p></div><div class="head-actions"><?php if($authNav->can('inventory.in')): ?><a class="btn success" href="<?=site_url('inventory/in')?>">+ Product IN</a><?php endif; ?><?php if($authNav->can('inventory.out')): ?><a class="btn primary" href="<?=site_url('inventory/out')?>">− Product OUT</a><?php endif; ?><a class="btn" href="<?=site_url('inventory/transactions')?>">Transaction history</a></div></div>
<div class="card"><div class="toolbar"><form class="search" method="get"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="6"/><path d="m16 16 5 5"/></svg><input name="q" value="<?=esc($q ?? '')?>" placeholder="Search product code or name…"></form><div class="pill-row"><span class="pill"><?=number_format(count($stocks))?> items</span><?php if(isset($lowCount)): ?><span class="pill"><?=number_format($lowCount)?> low stock</span><?php endif; ?></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Unit</th><th>Opening</th><th>Current</th><th>Minimum</th><th>Health</th></tr></thead><tbody><?php if(!$stocks): ?><tr><td colspan="6"><div class="empty"><strong>No inventory records</strong>Create products first to see stock balances here.</div></td></tr><?php else: foreach($stocks as $s): $stock=(float)$s['current_stock']; $min=(float)$s['minimum_stock']; $low=$stock<=$min; ?><tr><td><strong><?=esc($s['name'])?></strong><div class="muted mono"><?=esc($s['code'])?></div></td><td><?=esc($s['unit'])?></td><td><?=esc(inventory_quantity_label((float)$s['opening_stock'], (string)$s['unit']))?></td><td><strong><?=esc(inventory_quantity_label($stock, (string)$s['unit']))?></strong></td><td><?=esc(inventory_quantity_label($min, (string)$s['unit']))?></td><td><span class="badge <?=$low?'danger':'success'?>"><?=$low?'Low stock':'Healthy'?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
